/**
 * US-07 / US-09 / US-13 – Expense API service.
 *
 * This thin service layer wraps the HTTP client so the form and list hooks stay
 * framework-agnostic.
 *
 * - fetchExpenses(): Calls real FastAPI endpoint GET /api/v1/expenses with offset pagination.
 * - createExpense(), updateExpense(), deleteExpense(), undoDeleteExpense(): Stubs/implementations.
 *
 * The idempotency key is a UUID generated by the caller (useExpenseForm) so
 * that a network retry never saves the same expense twice (US-07).
 */

import { fastApiClient } from '@/services/api/fastApiClient';
import { ApiError } from '@/services/api/types';
import {
  PAYMENT_MODES,
  type CreateExpensePayload,
  type Expense,
  type PaymentMode,
  type UpdateExpensePayload,
} from '../types';

/** Generate a v4-like UUID without depending on `crypto.randomUUID` for RN compatibility. */
function generateUUID(): string {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

export function newIdempotencyKey(): string {
  return generateUUID();
}

// ── Backend Wire Types for /api/v1/expenses ──────────────────────────────────

export interface BackendExpenseItem {
  id: string;
  user_id: string;
  category_id: string;
  amount_minor: number;
  amount_paise?: number;
  description: string;
  expense_date: string;
  occurred_on?: string;
  notes?: string | null;
  merchant?: string | null;
  payment_mode?: string | null;
  receipt_id?: string | null;
  version: number;
  created_at: string;
  updated_at: string;
  deleted_at?: string | null;
}

export interface BackendExpenseListMeta {
  total: number;
  limit: number;
  offset: number;
  next_cursor?: string | null;
}

export interface BackendExpenseListResponse {
  data: BackendExpenseItem[];
  meta: BackendExpenseListMeta;
}

export interface FetchExpensesParams {
  limit?: number;
  offset?: number;
  categoryId?: string;
  from?: string;
  to?: string;
  query?: string;
}

export interface FetchExpensesResult {
  expenses: Expense[];
  total: number;
  limit: number;
  offset: number;
  hasMore: boolean;
  nextCursor?: string | null;
}

/**
 * Maps a backend ExpenseResponse to the mobile client's Expense domain model.
 * Preserves integer paise for monetary accuracy (NFR-M01).
 */
export function mapBackendExpenseToDomain(item: BackendExpenseItem): Expense {
  const rawMode = (item.payment_mode || '').toLowerCase();
  const paymentMode: PaymentMode = (PAYMENT_MODES as readonly string[]).includes(rawMode)
    ? (rawMode as PaymentMode)
    : 'other';

  return {
    id: String(item.id),
    amountPaise: item.amount_paise ?? item.amount_minor ?? 0,
    categoryId: String(item.category_id || 'other'),
    date: item.expense_date || item.occurred_on || '',
    paymentMode,
    notes: (item.notes && item.notes.trim()) ? item.notes : (item.description || ''),
    isRecurring: false,
    version: item.version ?? 1,
    createdAt: item.created_at || new Date().toISOString(),
    updatedAt: item.updated_at || new Date().toISOString(),
    description: item.description,
    merchant: item.merchant ?? undefined,
  };
}

/**
 * Fetches personal expenses with offset-based pagination and optional filtering.
 * Uses the shared ApiClient instance via public fastApiClient.get<T>().
 */
export async function fetchExpenses({
  limit = 20,
  offset = 0,
  categoryId,
  from,
  to,
  query,
}: FetchExpensesParams = {}): Promise<FetchExpensesResult> {
  const queryParams = new URLSearchParams();
  queryParams.set('limit', String(limit));
  queryParams.set('offset', String(offset));

  if (categoryId) {
    queryParams.set('category_id', categoryId);
  }
  if (from) {
    queryParams.set('from', from);
  }
  if (to) {
    queryParams.set('to', to);
  }
  if (query && query.trim()) {
    queryParams.set('q', query.trim());
  }

  const endpoint = `/api/v1/expenses?${queryParams.toString()}`;
  const raw = await fastApiClient.get<BackendExpenseListResponse>(endpoint);

  const rawItems = Array.isArray(raw?.data) ? raw.data : [];
  const meta = raw?.meta ?? {
    total: rawItems.length,
    limit,
    offset,
    next_cursor: null,
  };

  const expenses = rawItems.map(mapBackendExpenseToDomain);
  const total = typeof meta.total === 'number' ? meta.total : expenses.length;
  const hasMore = offset + expenses.length < total;

  return {
    expenses,
    total,
    limit: meta.limit ?? limit,
    offset: meta.offset ?? offset,
    hasMore,
    nextCursor: meta.next_cursor ?? null,
  };
}

